#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> gcdValues(std::vector<int>& nums, std::vector<long long>& queries) {
        int max_val = *std::max_element(nums.begin(), nums.end());
        std::vector<int> freq(max_val + 1, 0);
        for (int x : nums) freq[x]++;

        std::vector<long long> cnt(max_val + 1, 0);
        for (int g = max_val; g >= 1; --g) {
            long long c = 0;
            for (int mult = g; mult <= max_val; mult += g) {
                c += freq[mult];
            }
            long long total_pairs = c * (c - 1) / 2;
            for (int mult = 2 * g; mult <= max_val; mult += g) {
                total_pairs -= cnt[mult];
            }
            cnt[g] = total_pairs;
        }

        std::vector<long long> pref(max_val + 1, 0);
        for (int g = 1; g <= max_val; ++g) {
            pref[g] = pref[g - 1] + cnt[g];
        }

        std::vector<int> ans;
        ans.reserve(queries.size());
        for (long long q : queries) {
            int g = std::upper_bound(pref.begin(), pref.end(), q) - pref.begin();
            ans.push_back(g);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] gcdValues(int[] nums, long[] queries) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);

        int[] freq = new int[maxVal + 1];
        for (int x : nums) freq[x]++;

        long[] cnt = new long[maxVal + 1];
        for (int g = maxVal; g >= 1; g--) {
            long c = 0;
            for (int mult = g; mult <= maxVal; mult += g) {
                c += freq[mult];
            }
            long totalPairs = c * (c - 1) / 2;
            for (int mult = 2 * g; mult <= maxVal; mult += g) {
                totalPairs -= cnt[mult];
            }
            cnt[g] = totalPairs;
        }

        long[] pref = new long[maxVal + 1];
        for (int g = 1; g <= maxVal; g++) {
            pref[g] = pref[g - 1] + cnt[g];
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long q = queries[i];
            int low = 1, high = maxVal, res = maxVal;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (pref[mid] > q) {
                    res = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            ans[i] = res;
        }
        return ans;
    }
}

